// Configuration for the whole run.
const env = (k, dflt) => (typeof $env !== 'undefined' && $env[k] !== undefined && $env[k] !== '' ? $env[k] : dflt);
const flag = (k, dflt) => {
  const v = env(k, null);
  if (v === null) return dflt;
  return /^(1|true|yes|on)$/i.test(String(v));
};

const owners = String(env('COLLECT_010_OWNERS', 'Operator-Syn'))
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
if (!owners.length) throw new Error('COLLECT_010_OWNERS is empty');

// 0 means the whole history of every repository: no `since` is sent and the commit
// endpoint is paginated to its end. A positive value keeps a rolling window.
const windowDays = Number(env('COLLECT_010_WINDOW_DAYS', 0));
const maxCommitPages = Number(env('COLLECT_010_MAX_COMMIT_PAGES', 50));
// Force a full re-fetch of every repository, ignoring the cached copy. Use after
// changing what is collected, or to rebuild a cache you do not trust.
const forceFull = flag('COLLECT_010_FORCE_FULL_RESYNC', false);
// Stop collecting when this few API calls remain, so a run never dies mid-way with
// every remaining repository erroring. Cached data is preserved for the rest.
const rateReserve = Number(env('COLLECT_010_RATE_RESERVE', 25));
// Cold start: how many repositories a single run may collect for the first time. A first run
// against an empty database would otherwise fetch all of them in one burst — ~95 calls and four
// minutes here, more on an account with more history, and any interruption leaves no record of
// what is still outstanding.
const maxNewPerRun = Number(env('COLLECT_010_MAX_NEW_PER_RUN', 12));
const token = env('COLLECT_010_GITHUB_TOKEN', '');

const headers = { Accept: 'application/vnd.github+json', 'User-Agent': 'mnemora-collector' };
if (token) headers.Authorization = 'Bearer ' + token;

const now = new Date();
const until = now.toISOString();
const since =
  windowDays > 0 ? new Date(now.getTime() - windowDays * 24 * 3600 * 1000).toISOString() : null;

return [
  {
    json: {
      owners,
      since,
      until,
      history: since ? `last ${windowDays} days` : 'full history',
      maxCommitPages,
      forceFull,
      rateReserve,
  maxNewPerRun,
      headers,
      includeForks: flag('COLLECT_010_INCLUDE_FORKS', true),
      includeArchived: flag('COLLECT_010_INCLUDE_ARCHIVED', true),
    },
  },
];

// Discovers every public repository of each configured owner and brings the cache up
// to date, touching only what actually changed.
//
// Three collection modes per repository, cheapest first:
//   skipped      - pushed_at is unchanged since the cached copy, so nothing is fetched
//   incremental  - new commits only, via `since`, merged into the cached history
//   full         - the whole history, for a repository with no usable cache
//
// A repository whose history was rewritten (force-push) fails the incremental check and
// falls back to a full resync, so ghosts cannot accumulate.
const cfg = $('Build Plan').first().json;
const STATUS_FILE = 'collector-status.json';
const API = 'https://api.github.com';
const httpGet = this.helpers.httpRequest.bind(this.helpers);

// Tracks GitHub's remaining quota from response headers so the run can stop early
// instead of burning the last calls and then failing on every remaining repository.
let budget = null;
// Counted so the run can report what it cost. Headers tell us what remains; this tells us what
// we spent, which is the number a monthly budget question actually asks for.
let apiCalls = 0;
async function get(url, qs) {
  apiCalls++;
  const res = await httpGet({
    url,
    qs,
    headers: cfg.headers,
    json: true,
    timeout: 30000,
    returnFullResponse: true,
  });
  const h = res.headers || {};
  const raw = h['x-ratelimit-remaining'] !== undefined ? h['x-ratelimit-remaining'] : h['X-RateLimit-Remaining'];
  if (raw !== undefined && raw !== null && !Number.isNaN(Number(raw))) budget = Number(raw);
  return res.body;
}

// --- previous state, read from the database by the node before this one ------------
// The database is the source of truth for "what do we already have". The cache files are an
// export, not an input: moving or deleting them changes nothing about what this run decides.
// A row's pushed_at_utc answers "did this move since we last looked", which is the whole
// question the files used to answer.
const existing = {};
const known = [];
for (const item of $('Read State').all()) {
  const row = item.json || {};
  if (row.repository_id === undefined || row.repository_id === null || row.repository_id === '') continue;
  known.push(row);
  existing[String(row.full_name || '').toLowerCase()] = row;
}

// --- discovery ----------------------------------------------------------------
const repos = [];
// Every id the listing returned, including forks and archived repositories that the filters
// below drop. Archive detection compares against this, not against `repos`, or a filtered-out
// fork would look like a repository that vanished upstream.
const listedIds = new Set();
for (const owner of cfg.owners) {
  for (let page = 1; page <= 20; page++) {
    const batch = await get(`${API}/users/${owner}/repos`, { per_page: 100, page, sort: 'full_name' });
    const list = Array.isArray(batch) ? batch : [];
    for (const repo of list) {
      if (repo.id) listedIds.add(repo.id);
      if (repo.visibility !== 'public') continue;
      if (repo.fork && !cfg.includeForks) continue;
      if (repo.archived && !cfg.includeArchived) continue;
      repos.push(repo);
    }
    if (list.length < 100) break;
  }
}

// --- per repository -----------------------------------------------------------
const out = [];
// Records that must reach the database but must not touch the cache export: skipped
// repositories (no commit list) and failed fetches (would replace good data with nothing).
// Kept separate so the export branch's item order stays 1:1 with the files it writes.
const pipeOnly = [];
const status = [];
// A repository with no row, or a row still marked pending, is a cold-start fetch: it has never
// been collected. These are the expensive ones, so a run takes only so many.
let coldFetched = 0;
const coldCap = Number(cfg.maxNewPerRun) > 0 ? Number(cfg.maxNewPerRun) : Infinity;

for (const repo of repos) {
  const fullName = repo.full_name;
  const cacheFile = `github-public-cache__${String(fullName).toLowerCase().replace('/', '__')}.json`;
  const prev = existing[String(fullName).toLowerCase()] || null;
  const nowIso = new Date().toISOString();
  const isColdStart = !prev || prev.source_state === 'pending';

  // Cold-start budget reached: record it as pending so the database knows the repository exists
  // and is owed a collection, and so the dashboard can tell "not yet collected" from "empty".
  // Nothing is fetched, nothing is pruned, and the next run picks it up.
  if (isColdStart && coldFetched >= coldCap) {
    pipeOnly.push({
      json: {
        repository_id: repo.id, full_name: fullName, visibility: repo.visibility,
        default_branch: repo.default_branch, description: repo.description || null,
        is_fork: !!repo.fork, is_archived: !!repo.archived, html_url: repo.html_url,
        pushed_at_utc: repo.pushed_at, languages_bytes: (prev && prev.languages_bytes) || {},
        history: cfg.history, commit_count: 0, collection: 'pending',
        source_state: 'pending',
        source_error: 'pending: cold-start budget reached, not yet collected',
        refreshed_at_utc: nowIso, commits_omitted: true, cache_file: cacheFile,
      },
    });
    status.push({
      cache_file: cacheFile, full_name: fullName, collection: 'pending',
      refreshed_at_utc: nowIso, data_changed_at_utc: null, commit_count: 0,
      source_state: 'pending', source_error: 'cold-start budget reached',
    });
    continue;
  }
  if (isColdStart) coldFetched++;

  // 0. Out of quota: stop spending, keep whatever is already cached.
  if (budget !== null && budget <= cfg.rateReserve) {
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'deferred',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev ? prev.data_changed_at_utc || prev.refreshed_at_utc : null,
      commit_count: prev ? prev.commit_count : 0,
      source_state: prev ? prev.source_state : 'error',
      source_error: 'deferred: rate-limit reserve reached, cache left untouched',
    });
    continue;
  }

  // Compare instants, not strings: Postgres renders timestamptz as `2026-10-18 01:09:49+00`
  // while GitHub sends `2026-10-18T01:09:49Z`. String comparison never matches, which quietly
  // turned every "skipped" into a full refetch — 24 repositories and ~95 API calls per run.
  const sameInstant = (a, b) => {
    if (a === null || a === undefined || b === null || b === undefined) return !a && !b;
    const ta = new Date(a).getTime();
    const tb = new Date(b).getTime();
    if (Number.isNaN(ta) || Number.isNaN(tb)) return String(a) === String(b);
    return ta === tb;
  };
  const reuse = () =>
    prev &&
    Number(prev.repository_id) === repo.id &&
    prev.history === cfg.history &&
    prev.default_branch === repo.default_branch &&
    sameInstant(prev.pushed_at_utc, repo.pushed_at) &&
    !cfg.forceFull;

  // 1. Unchanged since the database was last refreshed: fetch nothing at all.
  if (reuse() && !prev.source_error) {
    // The record still goes to the pipeline, so refreshed_at_utc advances and the dashboard
    // can show "checked 2 minutes ago" honestly. Two flags keep that safe and non-destructive:
    //   commits_omitted    - the database must not prune rows for a list we never sent
    //   skip_cache_write   - the cache export must not be replaced with a hollow record
    let prevLanguages = prev.languages_bytes || {};
    if (typeof prevLanguages === 'string') {
      try { prevLanguages = JSON.parse(prevLanguages); } catch (e) { prevLanguages = {}; }
    }
    pipeOnly.push({
      json: {
        repository_id: repo.id,
        full_name: fullName,
        visibility: repo.visibility,
        default_branch: repo.default_branch,
        description: repo.description || null,
        is_fork: !!repo.fork,
        is_archived: !!repo.archived,
        html_url: repo.html_url,
        pushed_at_utc: repo.pushed_at,
        languages_bytes: prevLanguages,
        history: cfg.history,
        commit_count: Number(prev.commit_count) || 0,
        collection: 'skipped',
        source_state: prev.source_state || 'complete',
        source_error: prev.source_error || null,
        refreshed_at_utc: nowIso,
        commits_omitted: true,
        skip_cache_write: true,
        cache_file: cacheFile,
      },
    });
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'skipped',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev.data_changed_at_utc || prev.refreshed_at_utc,
      commit_count: Number(prev.commit_count) || 0,
      source_state: prev.source_state,
      source_error: prev.source_error || null,
    });
    continue;
  }

  let languages = (prev && prev.languages_bytes) || {};
  let commits = [];
  let state = 'complete';
  let error = null;
  let pages = 0;
  let mode = 'full';
  let preserved = false;

  try {
    languages = (await get(`${API}/repos/${fullName}/languages`)) || languages;
  } catch (e) {
    state = 'partial';
    error = `languages: ${e.message}`;
  }

  // Incremental is only valid when the previous copy covers the same history mode.
  // D2 (operator decision): a changed repository is re-collected in full. Merging is no
  // longer this node's job — the commits live as rows in the database, and prune-on-complete
  // keeps that list honest after a history rewrite. Incremental `since` returns when the
  // call budget justifies the extra reconciliation rule, not before.
  const canIncrement = false;

  try {
    if (canIncrement) {
      mode = 'incremental';
      // Overlap by an hour: author date and committer date can disagree, and a push
      // can land commits slightly out of order. Duplicates are removed by sha below.
      const newest = prev.commits.map((c) => c.committed_at_utc).filter(Boolean).sort().pop();
      const since = new Date(new Date(newest).getTime() - 3600 * 1000).toISOString();
      const fetched = [];
      for (let page = 1; page <= cfg.maxCommitPages; page++) {
        const raw = await get(`${API}/repos/${fullName}/commits`, { per_page: 100, page, since });
        const list = Array.isArray(raw) ? raw : [];
        pages = page;
        fetched.push(...list.filter((c) => c && c.sha));
        if (list.length < 100) break;
      }
      // Rewrite detection: the cached head must still exist upstream. If it does not,
      // history was rewritten and a merge would keep commits GitHub no longer has.
      const cachedHead = prev.commits[0] && prev.commits[0].sha;
      const stillPresent = !cachedHead || fetched.some((c) => c.sha === cachedHead);
      if (!stillPresent) {
        mode = 'full';
        state = 'partial';
        error = 'history rewritten upstream; re-collected in full';
        commits = [];
      } else {
        commits = fetched;
      }
    }

    if (mode === 'full') {
      for (let page = 1; page <= cfg.maxCommitPages; page++) {
        const qs = { per_page: 100, page };
        if (cfg.since) qs.since = cfg.since;
        const raw = await get(`${API}/repos/${fullName}/commits`, qs);
        const list = Array.isArray(raw) ? raw : [];
        pages = page;
        commits.push(...list.filter((c) => c && c.sha));
        if (list.length < 100) break;
        if (page === cfg.maxCommitPages) {
          state = 'partial';
          error = `commits: capped at ${cfg.maxCommitPages} pages (${commits.length} commits)`;
        }
      }
    }
  } catch (e) {
    const empty = /empty/i.test(String(e.message || ''));
    state = empty ? 'empty' : 'error';
    error = `commits: ${e.message}`;
    commits = [];
    // Preserve last-known-good: a failed fetch must never replace real history with
    // an empty list. The record is marked stale and the file is left on disk as-is.
    if (prev && Array.isArray(prev.commits) && prev.commits.length) {
      preserved = true;
      state = 'stale';
    }
  }

  const shape = (c) => ({
    sha: c.sha,
    html_url: c.html_url,
    message: (c.commit && c.commit.message ? c.commit.message : '').split('\n')[0],
    author: {
      login: c.author ? c.author.login : null,
      name: c.commit && c.commit.author ? c.commit.author.name : null,
      email: c.commit && c.commit.author ? c.commit.author.email : null,
    },
    authored_at_utc: c.commit && c.commit.author ? c.commit.author.date : null,
    committed_at_utc: c.commit && c.commit.committer ? c.commit.committer.date : null,
  });

  // Merge: incremental results join the cached history, deduped by sha, newest first.
  let detail;
  if (mode === 'incremental' && prev && !error) {
    const bySha = new Map();
    for (const c of prev.commits) bySha.set(c.sha, c);
    for (const c of commits) bySha.set(c.sha, shape(c));
    detail = [...bySha.values()].sort((a, b) =>
      String(b.committed_at_utc || '').localeCompare(String(a.committed_at_utc || '')),
    );
  } else {
    detail = commits.map(shape);
  }

  const authored = detail.map((c) => c.authored_at_utc).filter(Boolean).sort();
  const periodStart = authored.length ? authored[0] : (prev && prev.period_start_utc) || cfg.since;

  if (preserved) {
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'stale',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev.data_changed_at_utc || prev.refreshed_at_utc,
      commit_count: prev.commit_count,
      source_state: state,
      source_error: error,
    });
    continue;
  }

  (state === 'error' || state === 'stale' ? pipeOnly : out).push({
    json: {
      repository_id: repo.id,
      full_name: fullName,
      visibility: repo.visibility,
      default_branch: repo.default_branch,
      description: repo.description || null,
      is_fork: !!repo.fork,
      is_archived: !!repo.archived,
      html_url: repo.html_url,
      pushed_at_utc: repo.pushed_at,
      languages_bytes: languages,
      history: cfg.history,
      period_start_utc: periodStart,
      period_end_utc: cfg.until,
      commit_pages_fetched: pages,
      commit_count: detail.length,
      commit_count_definition:
        'Commits returned by the GitHub REST commits endpoint for the default branch, newest first; not an authored-contribution count.',
      collection: mode,
      source_state: state,
      source_error: error,
      refreshed_at_utc: nowIso,
      data_changed_at_utc: nowIso,
      cache_file: cacheFile,
      commits: detail,
    },
  });

  status.push({
    cache_file: cacheFile,
    full_name: fullName,
    collection: mode,
    refreshed_at_utc: nowIso,
    data_changed_at_utc: nowIso,
    commit_count: detail.length,
    source_state: state,
    source_error: error,
  });
}

// --- archived repositories ----------------------------------------------------
// Rows we know about, under an owner we just listed, that the listing no longer contains.
// They are archived by the database, never deleted, so their commits survive as history
// (decision D3). Only live rows are sent: re-archiving an archived row is a no-op anyway.
const ownerPrefixes = cfg.owners.map((o) => String(o).toLowerCase() + '/');
const archivedIds = known
  .filter((row) => !row.archived_at_utc)
  .filter((row) => ownerPrefixes.some((prefix) => String(row.full_name || '').toLowerCase().startsWith(prefix)))
  .filter((row) => !listedIds.has(Number(row.repository_id)))
  .map((row) => Number(row.repository_id));

// One small file per run: which repositories were checked and when. Written every run so
// the "last checked" signal survives without rewriting multi-hundred-kilobyte payloads.
out.push({
  json: {
    generated_at_utc: new Date().toISOString(),
    owners: cfg.owners,
    history: cfg.history,
    repository_count: status.length,
    repositories: status.sort((a, b) => a.cache_file.localeCompare(b.cache_file)),
    archived_repository_ids: archivedIds,
    api_calls: apiCalls,
    pipe_only_records: pipeOnly.map((i) => i.json),
    cache_file: STATUS_FILE,
  },
});

return out;

// Routes Collect's output to the pipeline.
//
// One request per repository record — including skipped repositories, whose records carry no
// commit list but still advance refreshed_at_utc. Plus a single request listing repositories
// that vanished from the listing, so the database can archive them instead of deleting them.
// The run-status item is not a database record and is dropped here; it still goes to the cache
// export, where it belongs.
const out = [];
let archived = [];
for (const item of $('Collect').all()) {
  const j = item.json || {};
  if (j.repository_id !== undefined && j.repository_id !== null && j.repository_id !== '') {
    out.push({ json: j });
  } else {
    // The run-status item carries two things the pipeline needs and the export does not:
    // records that must not overwrite the cache (skipped, failed), and repositories that
    // vanished upstream.
    if (Array.isArray(j.pipe_only_records)) out.push(...j.pipe_only_records.map((r) => ({ json: r })));
    if (Array.isArray(j.archived_repository_ids)) archived = j.archived_repository_ids;
  }
}
if (archived.length) out.push({ json: { archived_repository_ids: archived } });
return out;

// Claim the single-run lease before spending a single GitHub request.
//
// A schedule tick landing on top of a manual run would fetch the same 24 repositories twice.
// Writes stay correct either way — everything is keyed by sha and idempotent — but the calls
// are wasted, and on a bad day that is the difference between a run that finishes and one that
// hits the quota reserve halfway.
//
// The claim is held by persist (the only writer to the database); this node asks for it over the
// pipe and stays read-only itself. TTL bounds a crashed run: the lease expires rather than
// blocking forever.
const enabled = String($env.COLLECT_010_RUN_LOCK ?? 'true').toLowerCase();
if (['0', 'false', 'no', 'off'].includes(enabled)) {
  return [{ json: { run_lock: 'disabled' } }];
}

const ttl = Number($env.COLLECT_010_RUN_LOCK_TTL_SECONDS || 900);
const runId = $execution.id ? String($execution.id) : `run-${Date.now()}`;

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://n8n:5678/webhook/mnemora-commits',
  body: { run_claim: { action: 'acquire', run_id: runId, workflow: 'collect-010', ttl_seconds: ttl } },
  headers: { 'Content-Type': 'application/json' },
  json: true,
  timeout: 15000,
});

if (!res || res.acquired !== true) {
  const holder = res && res.holder ? res.holder : 'unknown';
  const expires = res && res.holder_expires_at_utc ? res.holder_expires_at_utc : 'unknown';
  throw new Error(
    `collector: another run holds the lease (run ${holder}, expires ${expires}). ` +
      `Refusing to duplicate the crawl. Clear it with: ` +
      `delete from mnemora_run_lock where lock_name = 'collector';`,
  );
}

const first = $input.first().json ?? {};
return [{ json: { ...first, run_lock: 'acquired', run_lock_id: runId, run_lock_ttl: ttl } }];

// Hand the lease back as soon as the fetching is done, so the next manual run is not blocked
// for the rest of the TTL. Deliberately non-fatal: failing to release must not fail a run that
// already stored its data — the TTL reclaims the lease anyway.
const upstream = $input.first().json ?? {};
const acquired = $('Acquire Run Lock').first().json;
if (!acquired || acquired.run_lock !== 'acquired') {
  return [{ json: { ...upstream, run_lock_released: false, reason: 'not held' } }];
}
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://n8n:5678/webhook/mnemora-commits',
    body: { run_claim: { action: 'release', run_id: acquired.run_lock_id } },
    headers: { 'Content-Type': 'application/json' },
    json: true,
    timeout: 15000,
  });
  return [{ json: { ...upstream, run_lock_released: !!(res && res.released) } }];
} catch (e) {
  return [{ json: { ...upstream, run_lock_released: false, reason: e.message } }];
}

// Record the run itself. Until now the only trace was collector-status.json, which every run
// overwrote, so yesterday's run left nothing behind in the product database.
//
// The counts come from two places and both are authoritative: the repository outcomes from the
// status item Collect produced, and the commit counts from what persist answered for each record.
// Nothing here is estimated.
const summaryItem = $('Collect').all().map((i) => i.json).find((j) => j.cache_file === 'collector-status.json') || {};
const rows = Array.isArray(summaryItem.repositories) ? summaryItem.repositories : [];
const mode = (m) => rows.filter((r) => r.collection === m).length;

let commitsSeen = 0, commitsNew = 0, commitsPruned = 0;
for (const item of $('Save to Pipe').all()) {
  const j = (item && item.json) || {};
  // Only repository responses carry these; the archive batch answers with its own shape.
  if (typeof j.commits_seen !== 'number') continue;
  commitsSeen += Number(j.commits_seen) || 0;
  commitsNew += Number(j.commits_new) || 0;
  commitsPruned += Number(j.commits_pruned) || 0;
}

const failed = rows.filter((r) => r.source_state === 'error' || r.source_state === 'stale').length;
const lock = $('Acquire Run Lock').first().json || {};
const plan = $('Build Plan').first().json || {};

const summary = {
  run_id: lock.run_lock_id || `adhoc-${Date.now()}`,
  workflow: 'collect-010',
  started_at_utc: plan.until || null,
  finished_at_utc: new Date().toISOString(),
  status: failed > 0 ? 'partial' : 'success',
  repositories_total: rows.length,
  repositories_fetched: mode('full'),
  repositories_skipped: mode('skipped'),
  repositories_pending: mode('pending'),
  repositories_failed: failed,
  repositories_archived: Array.isArray(summaryItem.archived_repository_ids) ? summaryItem.archived_repository_ids.length : 0,
  commits_seen: commitsSeen,
  commits_new: commitsNew,
  commits_pruned: commitsPruned,
  api_calls: Number(summaryItem.api_calls) || 0,
  note: failed > 0 ? `${failed} repositories did not complete` : null,
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://n8n:5678/webhook/mnemora-commits',
    body: { run_summary: summary },
    headers: { 'Content-Type': 'application/json' },
    json: true,
    timeout: 15000,
  });
  return [{ json: { ...($input.first().json || {}), run_recorded: true, run_id: summary.run_id } }];
} catch (e) {
  // A run that did its work but could not file its report should say so without failing the
  // storage that already happened. The lease is still released on the next node.
  return [{ json: { ...($input.first().json || {}), run_recorded: false, run_error: e.message } }];
}
